local isPlaying = true
local currentTime = 0

local audioFile = "sy8pooyVFMM_1780303123.mp3"
writefile(audioFile, game:HttpGet("https://raw.githubusercontent.com/Reirei990ultr/0/main/audios/sy8pooyVFMM_1780303123.mp3"))

local sound = Instance.new("Sound")
sound.SoundId = getcustomasset(audioFile)
sound.Volume = 0
sound.Looped = true
sound.Parent = game.Workspace

local function updateVideo()
    if not isPlaying then return end
    for f = 1, totalFrames do
        for y = 1, 16 do
            for x = 1, 16 do
                local pixel = pixelFrames[f] and pixelFrames[f][y] and pixelFrames[f][y][x]
                if pixel then
                    pixel.Visible = (f == currentFrame)
                end
            end
        end
    end
end

local function seekTo(seconds)
    local frameIndex = math.floor(seconds / (frameDelay / 1000)) + 1
    if frameIndex < 1 then frameIndex = 1 end
    if frameIndex > totalFrames then frameIndex = totalFrames end
    currentFrame = frameIndex
    currentTime = (currentFrame - 1) * (frameDelay / 1000)
    updateVideo()
    if sound then
        sound.TimePosition = currentTime
    end
end

for f = 1, totalFrames do
    pixelFrames[f] = {}
    for y = 1, 16 do
        pixelFrames[f][y] = {}
    end
end

for f = 1, totalFrames do
    for y = 1, 16 do
        for x = 1, 16 do
            local pixel = frameData[f][y][x]
            if pixel then
                local pixelFrame = Instance.new("Frame")
                pixelFrame.Size = UDim2.new(0, 4, 0, 4)
                pixelFrame.Position = UDim2.new(0, (x-1)*4, 0, (y-1)*4)
                pixelFrame.BackgroundColor3 = Color3.fromRGB(pixel[1], pixel[2], pixel[3])
                pixelFrame.BorderSizePixel = 0
                pixelFrame.Parent = fh
                pixelFrame.Visible = (f == 1)
                pixelFrames[f][y][x] = pixelFrame
            end
        end
    end
end

local gui = Instance.new("ScreenGui")
gui.Name = "VideoControls"
gui.Parent = pl:WaitForChild("PlayerGui")

local controls = Instance.new("Frame")
controls.Size = UDim2.new(0, 300, 0, 50)
controls.Position = UDim2.new(0.5, -150, 1, -60)
controls.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
controls.BackgroundTransparency = 0.5
controls.Parent = gui

local playBtn = Instance.new("TextButton")
playBtn.Size = UDim2.new(0, 60, 0, 40)
playBtn.Position = UDim2.new(0, 10, 0, 5)
playBtn.Text = "▶️"
playBtn.Parent = controls

local seekBack = Instance.new("TextButton")
seekBack.Size = UDim2.new(0, 50, 0, 40)
seekBack.Position = UDim2.new(0, 80, 0, 5)
seekBack.Text = "⏪"
seekBack.Parent = controls

local seekForward = Instance.new("TextButton")
seekForward.Size = UDim2.new(0, 50, 0, 40)
seekForward.Position = UDim2.new(0, 140, 0, 5)
seekForward.Text = "⏩"
seekForward.Parent = controls

local closeBtn = Instance.new("TextButton")
closeBtn.Size = UDim2.new(0, 50, 0, 40)
closeBtn.Position = UDim2.new(0, 200, 0, 5)
closeBtn.Text = "❌"
closeBtn.Parent = controls

local timeLabel = Instance.new("TextLabel")
timeLabel.Size = UDim2.new(0, 50, 0, 30)
timeLabel.Position = UDim2.new(0, 260, 0, 10)
timeLabel.Text = "0:00"
timeLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
timeLabel.BackgroundTransparency = 1
timeLabel.Parent = controls

local lastRenderTime = tick()

sound:Play()

local targetVolume = 0.5
local fadeInTime = 2
local totalDuration = 65
local fadeOutTime = 4

task.spawn(function()
    local steps = 20
    local stepTime = fadeInTime / steps
    for i = 1, steps do
        if sound then
            sound.Volume = targetVolume * (i / steps)
            task.wait(stepTime)
        end
    end
end)

playBtn.MouseButton1Click:Connect(function()
    isPlaying = not isPlaying
    if isPlaying then
        playBtn.Text = "▶️"
        sound:Resume()
        lastRenderTime = tick()
    else
        playBtn.Text = "⏸️"
        sound:Pause()
    end
end)

seekBack.MouseButton1Click:Connect(function()
    local newTime = math.max(0, currentTime - 5)
    seekTo(newTime)
    if not isPlaying then
        updateVideo()
    end
end)

seekForward.MouseButton1Click:Connect(function()
    local newTime = math.min(totalDuration, currentTime + 5)
    seekTo(newTime)
    if not isPlaying then
        updateVideo()
    end
end)

closeBtn.MouseButton1Click:Connect(function()
    sg:Destroy()
    gui:Destroy()
    sound:Stop()
    sound:Destroy()
end)

local function formatTime(sec)
    local minutes = math.floor(sec / 60)
    local seconds = math.floor(sec % 60)
    return string.format("%d:%02d", minutes, seconds)
end

R.RenderStepped:Connect(function()
    if isPlaying then
        local now = tick()
        local delta = now - lastRenderTime
        if delta >= frameDelay / 1000 then
            local frameStep = math.floor(delta / (frameDelay / 1000))
            currentFrame = currentFrame + frameStep
            lastRenderTime = now
            if currentFrame > totalFrames then
                currentFrame = 1
            end
            currentTime = (currentFrame - 1) * (frameDelay / 1000)
            updateVideo()
            if sound then
                sound.TimePosition = currentTime
            end
        end
    end
    timeLabel.Text = formatTime(currentTime) .. " / " .. formatTime(totalDuration)
end)

task.delay(totalDuration - fadeOutTime, function()
    local steps = 20
    local stepTime = fadeOutTime / steps
    local startVolume = sound.Volume
    for i = 1, steps do
        if sound then
            sound.Volume = startVolume * (1 - (i / steps))
            task.wait(stepTime)
        end
    end
end)

game:GetService("Debris"):AddItem(sound, totalDuration)
task.delay(totalDuration, function()
    sg:Destroy()
    gui:Destroy()
end)